import 'package:family_veda/models/appointment.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('parses an appointment and its embedded doctor', () {
    final appointment = Appointment.fromJson({
      'id': 'appt-1',
      'memberId': 'mem-1',
      'memberDisplayName': 'Kavindu',
      'familyName': 'The Silvas',
      'startsAt': '2026-10-05T09:30:00Z',
      'durationMinutes': 45,
      'reason': 'Follow-up',
      'status': 'Confirmed',
      'doctor': {'id': 'doc-1', 'displayName': 'Nadeesha Fernando', 'specialty': 'GP'},
    });

    expect(appointment.id, 'appt-1');
    expect(appointment.durationMinutes, 45);
    expect(appointment.doctor?.displayName, 'Nadeesha Fernando');
    expect(appointment.status, AppointmentStatus.confirmed);
  });

  test('friendly status labels are patient-facing, not raw enum names', () {
    expect(AppointmentStatus.requested.friendlyLabel, 'Awaiting doctor');
    expect(AppointmentStatus.confirmed.friendlyLabel, 'Confirmed');
    expect(AppointmentStatus.completed.friendlyLabel, 'Completed');
    expect(AppointmentStatus.cancelled.friendlyLabel, 'Cancelled');
    expect(AppointmentStatus.noShow.friendlyLabel, 'Missed appointment');
  });

  test('maps unknown API status strings to unknown, not a crash', () {
    expect(AppointmentStatus.fromApi('SomethingNew'), AppointmentStatus.unknown);
    expect(AppointmentStatus.fromApi(null), AppointmentStatus.unknown);
  });

  test('only Requested and Confirmed appointments are cancellable', () {
    expect(AppointmentStatus.requested.isCancellable, isTrue);
    expect(AppointmentStatus.confirmed.isCancellable, isTrue);
    expect(AppointmentStatus.completed.isCancellable, isFalse);
    expect(AppointmentStatus.cancelled.isCancellable, isFalse);
    expect(AppointmentStatus.noShow.isCancellable, isFalse);
  });

  test('missing optional fields default safely', () {
    final appointment = Appointment.fromJson({
      'id': 'appt-2',
      'memberId': 'mem-2',
      'startsAt': '2026-10-05T09:30:00Z',
      'status': 'Requested',
    });
    expect(appointment.memberDisplayName, 'Family member');
    expect(appointment.durationMinutes, 30);
    expect(appointment.reason, '');
    expect(appointment.doctor, isNull);
  });
}
